import{_ as a,c as n,o as t,ae as o}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Upgrade and Activate Ninja Tables Pro License Key","description":"Upgrade and Activate Ninja Tables Pro License Key","frontmatter":{"title":"Upgrade and Activate Ninja Tables Pro License Key","description":"Upgrade and Activate Ninja Tables Pro License Key"},"headers":[],"relativePath":"guide/getting-started/upgrade-to-ninja-tables-pro-add-on-and-activate-ninja-tables-pro-license-key.md","filePath":"guide/getting-started/upgrade-to-ninja-tables-pro-add-on-and-activate-ninja-tables-pro-license-key.md"}'),i={name:"guide/getting-started/upgrade-to-ninja-tables-pro-add-on-and-activate-ninja-tables-pro-license-key.md"};function r(s,e,l,d,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="upgrade-and-activate-ninja-tables-pro-license-key" tabindex="-1">Upgrade and Activate Ninja Tables Pro License Key <a class="header-anchor" href="#upgrade-and-activate-ninja-tables-pro-license-key" aria-label="Permalink to &quot;Upgrade and Activate Ninja Tables Pro License Key&quot;">​</a></h1><p>Before you install Ninja Tables Pro, make sure you have the Free Version of Ninja Tables already installed on your site. By upgrading to the Ninja Tables Pro add-on, you can access many features. Here is how you can upgrade <strong>Ninja Tables</strong> -</p><ul><li>First, go to <a href="https://wpmanageninja.com/downloads/ninja-tables-pro-add-on/" target="_blank" rel="noreferrer">wpmanageninja.com</a> and purchase the Ninja Tables Pro Add-on.</li><li>Sign-up for WPManageNinja if you are a new user. This account will be required to provide you with the License Key and <strong>Support</strong>, if necessary. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-1.png" alt="Wpmanageninja login page"></li><li>Then fill in your payment details for the transaction to go through. After you log in to the dashboard, click on the** Download** button. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-2-1024x372.png" alt="Download .zip"></li><li>The Ninja Tables Pro Add-on will be downloaded to your Computer in .zip format.</li><li>Or, you can click on the <strong>Upgrade</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-3-1024x368.png" alt="Upgrade button"></li><li>Now go to your website’s WordPress Dashboard. Click on <strong>Plugins</strong> → <strong>Installed Plugins</strong> → <strong>Add New</strong> → <strong>Upload Plugin</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-4-1024x198.png" alt="Upload Plugin"></li><li>Congratulations! Ninja Tables Pro-add-on is successfully installed in your domain. Activate the plugin from your Plugins list.</li><li><strong>DO NOT DEACTIVATE OR DELETE</strong> the Ninja Tables plugin from the plugins list. The Pro add-on won’t work if the Free version of the plugin is removed.</li></ul><h2 id="ninja-tables-pro-license-key" tabindex="-1">Ninja Tables Pro License Key <a class="header-anchor" href="#ninja-tables-pro-license-key" aria-label="Permalink to &quot;Ninja Tables Pro License Key&quot;">​</a></h2><p>A **License Key **will be asked when you will be going to use the Pro features for the first time. You can retrieve the License you purchased from your dashboard. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-5-1024x362.png" alt="License Key"></p><ul><li>Copy the Key and paste it into the License key input field of the Ninja Tables Pro <strong>License</strong> tab &amp; Click on the **Activate Ninja Tables Pro **button. <img src="https://ninjatables.com/wp-content/uploads/2023/01/upgrade-to-pro-6-1024x285.png" alt="Activate Ninja Tables Pro"> Now you can enjoy all the awesome Premium features of the Ninja Tables Pro Add-on!</li></ul>',6)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
